SELECT * FROM leetcode_problem_bank 
WHERE quality_score BETWEEN #{minQuality} AND #{maxQuality}
ORDER BY quality_score DESC

SELECT p.* FROM leetcode_problem_bank p
WHERE p.id IN (
    SELECT problem_id FROM leetcode_problem_tag
    WHERE tag_name IN

        #{tagName}

    GROUP BY problem_id
    HAVING COUNT(DISTINCT tag_name) = #{tagNames.size}
)
ORDER BY p.quality_score DESC
